//! Transactional cache-group certificate layer.
//!
//! Keeps the last committed configuration of one session and certifies
//! proposed reconfigurations.  Committed state is mutated only when a
//! proposal is accepted; evaluation happens entirely in stamp-guarded scratch
//! space so rejected or stale proposals leave every committed value intact.

use crate::solver::SolverProblem;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Task {
    pub template: usize,
    pub group: usize,
    pub weight: u64,
    pub class: u64,
    pub pinned: bool,
}

#[derive(Clone, Debug)]
pub enum Edit {
    Move(usize, usize), Weight(usize, u64), Class(usize, u64), Bind(usize, usize),
    Pin(usize, bool), Quota(usize, u64), Budget(usize, u64), Cap(usize, u64),
}

#[derive(Clone, Default)]
