impl Ledger {
    pub fn new(
        problem: &SolverProblem,
        tasks: Vec<Task>,
        quotas: Vec<u64>,
        budgets: Vec<u64>,
        capacities: Vec<u64>,
    ) -> Result<Self, String> {
        let nodes = problem.num_nodes;
        if nodes == 0 || capacities.len() != nodes {
            return Err("capacity table".into());
        }
        let groups = quotas.len();
        if groups == 0 || budgets.len() != groups {
            return Err("group table".into());
        }
        let words = (nodes + 63) / 64;
        let templates = problem.demands.len();
        let task_count = tasks.len();

        let mut src_group = vec![usize::MAX; nodes];
        for (gid, members) in problem.source_merge_groups.iter().enumerate() {
            for &node in members {
                if let Some(slot) = src_group.get_mut(node) {
                    *slot = gid;
                }
            }
        }

        let mut tmpl_dom = vec![0u64; templates];
        let mut tmpl_fp = vec![0u64; templates * words];
        for (tid, demand) in problem.demands.iter().enumerate() {
            let domain = match &problem.demand_merge_classes {
                Some(classes) => classes.get(tid).copied().unwrap_or(usize::MAX),
                None => *src_group.get(demand.src).unwrap_or(&usize::MAX),
            };
            if domain == usize::MAX {
                return Err("template domain".into());
            }
            if let Some(Ok(domain)) = u64::try_from(domain).ok().map(Ok).ok() {
                tmpl_dom[tid] = domain;
            } else {
                return Err("template domain".into());
            }
            for &node in &demand.footprint {
                if node >= nodes {
                    return Err("template footprint".into());
                }
                tmpl_fp[tid * words + node / 64] |= 1u64 << (node % 64);
            }
        }

        let mut ledger = Ledger {
            nodes,
            words,
            groups,
            templates,
            revision: 0,
            caps: capacities,
            usage: vec![0u64; nodes],
            quota: quotas,
            budget: budgets,
            g_cnt: vec![0u32; groups],
            g_load: vec![0u64; groups],
            g_fpc: vec![0u32; groups],
            g_key_d: vec![0u64; groups],
            g_key_c: vec![0u64; groups],
            g_pinned: vec![0u32; groups],
            g_ref: vec![0u32; groups * nodes],
            g_fp: vec![0u64; groups * words],
            tasks,
            tmpl_dom,
            tmpl_fp,
            active: 0,
            slots: 0,
            total_weight: 0,
            total_pins: 0,
            stamp: 0,
            tk_mark: vec![0u32; task_count],
            tk_group: vec![0u32; task_count],
            tk_temp: vec![0u32; task_count],
            tk_weight: vec![0u64; task_count],
            tk_class: vec![0u64; task_count],
            tk_pin: vec![0u8; task_count],
            touched: Vec::with_capacity(task_count.min(1024)),
            gr_mark: vec![0u32; groups],
            qd_mark: vec![0u32; groups],
            dirty: Vec::new(),
            outs: vec![Vec::new(); groups],
            ins: vec![Vec::new(); groups],
            pq_quota: vec![0u64; groups],
            pq_budget: vec![0u64; groups],
            p_cnt: vec![0u32; groups],
            p_load: vec![0u64; groups],
            p_fpc: vec![0u32; groups],
            p_key_d: vec![0u64; groups],
            p_key_c: vec![0u64; groups],
            p_mixed: vec![0u8; groups],
            p_work: vec![0u8; groups],
            p_ref: vec![0u32; groups * nodes],
            p_fp: vec![0u64; groups * words],
            nd_mark: vec![0u32; nodes],
            delta: vec![0i64; nodes],
            pcap: vec![0u64; nodes],
            affected: Vec::new(),
            keys: Vec::new(),
        };
        ledger.build()?;
        Ok(ledger)
    }

    /// Folds the initial task assignment into the group tables and requires
    /// the resulting configuration to be legal.
    fn build(&mut self) -> Result<(), String> {
        for tid in 0..self.tasks.len() {
            let task = self.tasks[tid];
            if task.group >= self.groups || task.template >= self.templates {
                return Err("task reference".into());
            }
            let group = task.group;
            self.total_weight = self
                .total_weight
                .checked_add(task.weight)
                .ok_or("weight overflow")?;
            if task.pinned {
                self.total_pins += 1;
                self.g_pinned[group] += 1;
            }
            self.g_cnt[group] += 1;
            self.g_load[group] = self
                .g_load[group]
                .checked_add(task.weight)
                .ok_or("load overflow")?;
            let (dom, class) = (self.tmpl_dom[task.template], task.class);
            if self.g_cnt[group] == 1 {
                self.g_key_d[group] = dom;
                self.g_key_c[group] = class;
            } else if self.g_key_d[group] != dom || self.g_key_c[group] != class {
                return Err("illegal initial configuration".into());
            }
            let tb = task.template * self.words;
            let gb = group * self.nodes;
            for word in 0..self.words {
                let mut bits = self.tmpl_fp[tb + word];
                while bits != 0 {
                    let node = word * 64 + bits.trailing_zeros() as usize;
                    bits &= bits - 1;
                    if self.g_ref[gb + node] == 0 {
                        self.g_fp[group * self.words + word] |= 1u64 << (node % 64);
                        self.g_fpc[group] += 1;
                    }
                    self.g_ref[gb + node] += 1;
                }
            }
        }

        for group in 0..self.groups {
            if self.g_cnt[group] == 0 {
                continue;
            }
            self.active += 1;
            if self.quota[group] == 0 || !self.works(group) {
                return Err("illegal initial configuration".into());
            }
        }

        for node in 0..self.nodes {
            let mut used = 0u64;
            for group in 0..self.groups {
                if self.g_ref[group * self.nodes + node] > 0 {
                    used = used.checked_add(self.quota[group]).ok_or("reserve overflow")?;
                }
            }
            self.usage[node] = used;
            self.slots += used as i64;
            if used > self.caps[node] {
                return Err("illegal initial configuration".into());
            }
        }
        Ok(())
    }

    #[inline]
    fn works(&self, group: usize) -> bool {
        (self.g_load[group] as u128) <= (self.quota[group] as u128) * (self.budget[group] as u128)
    }

    /// Recomputes the derived proposal row of one dirty group.
    fn evaluate_group(&mut self, group: usize) {
        let n = self.nodes;
        let w = self.words;
        let gb = group * n;
        let gwb = group * w;
        let outs = std::mem::take(&mut self.outs[group]);
        let ins = std::mem::take(&mut self.ins[group]);

        self.p_ref[gb..gb + n].copy_from_slice(&self.g_ref[gb..gb + n]);
        for word in 0..w {
            self.p_fp[gwb + word] = 0;
        }

        for &task in &outs {
            let tb = self.tasks[task].template * w;
            for word in 0..w {
                let mut bits = self.tmpl_fp[tb + word];
                while bits != 0 {
                    let node = word * 64 + bits.trailing_zeros() as usize;
                    bits &= bits - 1;
                    self.p_ref[gb + node] -= 1;
                }
            }
        }
        for &task in &ins {
            let tb = self.tk_temp[task] as usize * w;
            for word in 0..w {
                let mut bits = self.tmpl_fp[tb + word];
                while bits != 0 {
                    let node = word * 64 + bits.trailing_zeros() as usize;
                    bits &= bits - 1;
                    self.p_ref[gb + node] += 1;
                }
            }
        }

        let mut fpc = 0u32;
        for node in 0..n {
            if self.p_ref[gb + node] > 0 {
                self.p_fp[gwb + node / 64] |= 1u64 << (node % 64);
                fpc += 1;
            }
        }
        self.p_fpc[group] = fpc;

        let mut out_weight = 0u64;
        for &task in &outs {
            out_weight += self.tasks[task].weight;
        }
        let mut in_weight = 0u64;
        for &task in &ins {
            in_weight += self.tk_weight[task];
        }
        let retained = self.g_cnt[group] as usize - outs.len();
        self.p_cnt[group] = (retained + ins.len()) as u32;
        self.p_load[group] = self.g_load[group] - out_weight + in_weight;

        // Members that no edit touched all shared the committed group key, so
        // the proposal key multiset is that key (when at least one such member
        // stays) plus the key of every task assigned to this group.
        self.keys.clear();
        self.keys.reserve(ins.len());
        for &task in &ins {
            self.keys.push((self.tmpl_dom[self.tk_temp[task] as usize], self.tk_class[task]));
        }
        self.keys.sort_unstable();
        self.keys.dedup();
        let base = (self.g_key_d[group], self.g_key_c[group]);
        let keeps_base = retained > 0;
        let base_present = keeps_base && self.keys.binary_search(&base).is_ok();
        let distinct = self.keys.len() + if keeps_base && !base_present { 1 } else { 0 };
        self.p_mixed[group] = if distinct > 1 { 1 } else { 0 };
        if distinct == 1 {
            let key = if self.keys.len() == 1 { self.keys[0] } else { base };
            self.p_key_d[group] = key.0;
            self.p_key_c[group] = key.1;
        } else {
            self.p_key_d[group] = 0;
            self.p_key_c[group] = 0;
        }

        let quota = self.pq_quota[group];
        let budget = self.pq_budget[group];
        let load = self.p_load[group] as u128;
        self.p_work[group] =
            if self.p_cnt[group] > 0 && (quota == 0 || load > quota as u128 * budget as u128) {
                1
            } else {
                0
            };

        // reservation delta over the symmetric difference of footprints
        let old_quota = self.quota[group] as i64;
        let new_quota = quota as i64;
        for word in 0..w {
            let mut bits = self.g_fp[gwb + word];
            while bits != 0 {
                let node = word * 64 + bits.trailing_zeros() as usize;
                bits &= bits - 1;
                if node < n {
                    self.touch_node(node);
                    self.delta[node] -= old_quota;
                }
            }
        }
        for word in 0..w {
            let mut bits = self.p_fp[gwb + word];
            while bits != 0 {
                let node = word * 64 + bits.trailing_zeros() as usize;
                bits &= bits - 1;
                if node < n {
                    self.touch_node(node);
                    self.delta[node] += new_quota;
                }
            }
        }

        self.outs[group] = outs;
        self.ins[group] = ins;
    }

    fn touch_node(&mut self, node: usize) {
        if self.nd_mark[node] != self.stamp {
            self.nd_mark[node] = self.stamp;
            self.delta[node] = 0;
            self.pcap[node] = self.caps[node];
            self.affected.push(node);
        }
    }

    fn touch_task(&mut self, task: usize) -> Result<(), String> {
        if task >= self.tasks.len() {
            return Err("task id".into());
        }
        if self.tk_mark[task] != self.stamp {
            self.tk_mark[task] = self.stamp;
            let current = self.tasks[task];
            self.tk_group[task] = current.group as u32;
            self.tk_temp[task] = current.template as u32;
            self.tk_weight[task] = current.weight;
            self.tk_class[task] = current.class;
            self.tk_pin[task] = current.pinned as u8;
            self.touched.push(task);
            let group = current.group;
            self.touch_group(group);
        }
        Ok(())
    }

    fn touch_group(&mut self, group: usize) {
        if self.gr_mark[group] != self.stamp {
            self.gr_mark[group] = self.stamp;
            self.pq_quota[group] = self.quota[group];
            self.pq_budget[group] = self.budget[group];
            self.outs[group].clear();
            self.ins[group].clear();
            self.dirty.push(group);
        }
    }

    fn proposal(&mut self, edits: &[Edit]) -> Result<Option<[u64; 4]>, String> {
        self.stamp += 1;
        self.touched.clear();
        self.dirty.clear();
        self.affected.clear();

        for edit in edits {
            match *edit {
                Edit::Move(task, group) => {
                    if group >= self.groups {
                        return Err("group id".into());
                    }
                    self.touch_task(task)?;
                    self.tk_group[task] = group as u32;
                    self.touch_group(group);
                }
                Edit::Weight(task, value) => {
                    self.touch_task(task)?;
                    self.tk_weight[task] = value;
                }
                Edit::Class(task, value) => {
                    self.touch_task(task)?;
                    self.tk_class[task] = value;
                }
                Edit::Bind(task, template) => {
                    if template >= self.templates {
                        return Err("template id".into());
                    }
                    self.touch_task(task)?;
                    self.tk_temp[task] = template as u32;
                }
                Edit::Pin(task, value) => {
                    self.touch_task(task)?;
                    self.tk_pin[task] = value as u8;
                }
                Edit::Quota(group, value) => {
                    if group >= self.groups {
                        return Err("group id".into());
                    }
                    self.touch_group(group);
                    self.pq_quota[group] = value;
                }
                Edit::Budget(group, value) => {
                    if group >= self.groups {
                        return Err("group id".into());
                    }
                    self.touch_group(group);
                    self.pq_budget[group] = value;
                }
                Edit::Cap(node, value) => {
                    if node >= self.nodes {
                        return Err("node id".into());
                    }
                    self.touch_node(node);
                    self.pcap[node] = value;
                }
            }
        }

        for &task in &self.touched {
            let from = self.tasks[task].group;
            let to = self.tk_group[task] as usize;
            self.outs[from].push(task);
            self.ins[to].push(task);
        }

        let mut capacity = 0u64;
        let mut mixed = 0u64;
        let mut work = 0u64;
        for index in 0..self.dirty.len() {
            let group = self.dirty[index];
            self.evaluate_group(group);
            mixed += self.p_mixed[group] as u64;
            work += self.p_work[group] as u64;
            if self.pq_quota[group] != self.quota[group] {
                self.qd_mark[group] = self.stamp;
            }
        }
        for &node in &self.affected {
            let used = self.usage[node] as i64 + self.delta[node];
            if used > self.pcap[node] as i64 {
                capacity += 1;
            }
        }

        // A pinned task protects its group, template, weight, class and the
        // quota of the group it belonged to at the beginning of the
        // transaction; each protected task is counted at most once.
        let mut pins = 0u64;
        for index in 0..self.dirty.len() {
            let group = self.dirty[index];
            if self.qd_mark[group] == self.stamp {
                pins += self.g_pinned[group] as u64;
            }
        }
        for &task in &self.touched {
            let current = self.tasks[task];
            if !current.pinned || self.qd_mark[current.group] == self.stamp {
                continue;
            }
            if self.tk_group[task] as usize != current.group
                || self.tk_temp[task] as usize != current.template
                || self.tk_weight[task] != current.weight
                || self.tk_class[task] != current.class
            {
                pins += 1;
            }
        }

        Ok(Some([capacity, mixed, work, pins]))
    }

    fn commit(&mut self) {
        for index in 0..self.touched.len() {
            let task = self.touched[index];
            let current = self.tasks[task];
            let to = self.tk_group[task] as usize;
            let pinned_old = current.pinned as u32;
            let pinned_new = self.tk_pin[task] as u32;
            if current.group == to {
                self.g_pinned[to] = (self.g_pinned[to] - pinned_old + pinned_new) as u32;
            } else {
                self.g_pinned[current.group] -= pinned_old;
                self.g_pinned[to] += pinned_new;
            }
            self.total_weight = self.total_weight - current.weight + self.tk_weight[task];
            self.total_pins = self.total_pins - pinned_old as u64 + pinned_new as u64;
            self.tasks[task] = Task {
                template: self.tk_temp[task] as usize,
                group: to,
                weight: self.tk_weight[task],
                class: self.tk_class[task],
                pinned: self.tk_pin[task] != 0,
            };
        }

        for index in 0..self.dirty.len() {
            let group = self.dirty[index];
            let n = self.nodes;
            let w = self.words;
            if self.g_cnt[group] == 0 && self.p_cnt[group] > 0 {
                self.active += 1;
            } else if self.g_cnt[group] > 0 && self.p_cnt[group] == 0 {
                self.active -= 1;
            }
            let gb = group * n;
            self.g_ref[gb..gb + n].copy_from_slice(&self.p_ref[gb..gb + n]);
            let gwb = group * w;
            self.g_fp[gwb..gwb + w].copy_from_slice(&self.p_fp[gwb..gwb + w]);
            self.g_cnt[group] = self.p_cnt[group];
            self.g_load[group] = self.p_load[group];
            self.g_fpc[group] = self.p_fpc[group];
            self.g_key_d[group] = self.p_key_d[group];
            self.g_key_c[group] = self.p_key_c[group];
            self.quota[group] = self.pq_quota[group];
            self.budget[group] = self.pq_budget[group];
        }

        for index in 0..self.affected.len() {
            let node = self.affected[index];
            let used = self.usage[node] as i64 + self.delta[node];
            self.slots += self.delta[node];
            self.usage[node] = used as u64;
            self.caps[node] = self.pcap[node];
        }
        self.revision += 1;
    }

    pub fn certificate(&self, query: &Query) -> Certificate {
        let groups = query
            .groups
            .iter()
            .map(|&id| {
                let empty = self.g_cnt[id] == 0;
                [
                    id as i64,
                    self.g_cnt[id] as i64,
                    self.g_load[id] as i64,
                    self.quota[id] as i64,
                    self.budget[id] as i64,
                    self.g_fpc[id] as i64,
                    if empty { -1 } else { self.g_key_d[id] as i64 },
                    if empty { -1 } else { self.g_key_c[id] as i64 },
                ]
            })
            .collect();
        let nodes = query
            .nodes
            .iter()
            .map(|&id| [id as u64, self.usage[id], self.caps[id]])
            .collect();
        let tasks = query
            .tasks
            .iter()
            .map(|&id| {
                let task = self.tasks[id];
                [
                    id as u64,
                    task.group as u64,
                    task.template as u64,
                    task.weight,
                    task.class,
                    task.pinned as u64,
                ]
            })
            .collect();
        Certificate {
            totals: [self.active, self.slots as u64, self.total_weight, self.total_pins],
            groups,
            nodes,
            tasks,
        }
    }

    pub fn transact(&mut self, expected: u64, edits: &[Edit], query: &Query) -> Result<Outcome, String> {
        if expected != self.revision {
            return Ok(Outcome {
                accepted: false,
                revision: self.revision,
                violations: None,
                certificate: self.certificate(query),
            });
        }
        let violations = self.proposal(edits)?.unwrap_or([0, 0, 0, 0]);
        let accepted = violations.iter().all(|&count| count == 0);
        if accepted {
            self.commit();
        }
        let certificate = self.certificate(query);
        Ok(Outcome { accepted, revision: self.revision, violations: Some(violations), certificate })
    }
}
